import React from 'react';
import { Box, Typography } from '@mui/material';
import { CHART_UNIT_CAPTIONS, chartPlotBoxSx, centeredChartColumnSx } from '../../constants/carbonVisualization';

export type CarbonChartUnitKind = 'emissionsKg' | 'emissionsPercent' | 'score' | 'count' | 'none';

export interface CarbonChartFrameProps {
  children: React.ReactNode;
  height?: number;
  maxWidth?: number;
  unitKind?: CarbonChartUnitKind;
  unitCaption?: string;
  ariaLabel?: string;
}

const CarbonChartFrame: React.FC<CarbonChartFrameProps> = ({
  children,
  height = 280,
  maxWidth = 720,
  unitKind = 'emissionsKg',
  unitCaption,
  ariaLabel,
}) => {
  const caption =
    unitCaption
    || (unitKind !== 'none' ? CHART_UNIT_CAPTIONS[unitKind] : undefined);

  return (
    <Box sx={centeredChartColumnSx}>
      <Box
        role={ariaLabel ? 'img' : undefined}
        aria-label={ariaLabel}
        sx={chartPlotBoxSx(height, maxWidth)}
      >
        {children}
      </Box>
      {caption ? (
        <Typography
          variant="caption"
          color="text.secondary"
          display="block"
          sx={{ mt: 0.75, textAlign: 'center', maxWidth }}
        >
          {caption}
        </Typography>
      ) : null}
    </Box>
  );
};

export default CarbonChartFrame;
